; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: ti89 (TI-89 / 92+ / V200 (68000, AMS)), starts in turbo mode
; ============================================================

			org 0

;## ntc_md_vectors ntc_ti89_boot
; (the 68k backend requires this section be named ntc_md_vectors - the generic
;  "68k start" slot. On AMS there is no program-owned vector table; this is just
;  the entry. ;!!TI89? the real AMS nostub header/reloc goes here - stubbed.)
			bra ntc_ti89_boot

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dc.l kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 17: Mode 1
			dc.l kw_model, 1

			; main.bas 18: Print "AMSDOS test on "; System.Platform
			dc.l kw_printstrvar, str1
			dc.l kw_printnl

			; main.bas 19: Print "Devices "; FileSystem.Devices(); " - using "; FileSystem.CurrentDevice()
			dc.l kw_printstrvar, str2
			dc.l kw_printnl

			; main.bas 20: Print "Volumes "; FileSystem.Volumes(); " - using "; FileSystem.CurrentVolume()
			dc.l kw_printstrvar, str3
			dc.l kw_printnl

			; main.bas 21: Wait
			dc.l p_wait_c

			; main.bas 23: For i = 0 To 9 : a(i) = 1000 - i * 50 : Next
			dc.l kw_ztov, var_i
for1_t:
			dc.l kw_mulvl, var_i, 50, tmp2
			dc.l kw_sublv, 1000, tmp2, tmp1
			dc.l kw_aset, arr_a, var_i, tmp1
			dc.l kw_next1l, var_i, 9, for1_t
for1_e:

			; main.bas 24: r = FileSystem.Save("AMS1.DAT", VarPtr(a), 20)
			dc.l kw_ztov, var_r

			; main.bas 25: Print "Save AMS1.DAT:"; r
			dc.l kw_printstrvar, str5
			dc.l kw_printint, var_r
			dc.l kw_printnl

			; main.bas 26: r = FileSystem.Load("AMS1.DAT", VarPtr(b), 20)
			dc.l kw_ztov, var_r

			; main.bas 27: Print "Load AMS1.DAT:"; r; " -"; b(0); " ..."; b(9)
			dc.l kw_printstrvar, str6
			dc.l kw_printint, var_r
			dc.l kw_printstrvar, str7
			dc.l kw_printint, arr_b
			dc.l kw_printstrvar, str8
			dc.l kw_printint, arr_b+18
			dc.l kw_printnl

			; main.bas 28: t = Ticks
			dc.l kw_ticks, tmp0
			dc.l kw_vtov, tmp0, var_t

			; main.bas 29: Frame : Frame
			dc.l kw_frame
			dc.l kw_frame

			; main.bas 30: Print "Ticks still counting:"; IIf(Ticks <> t Or System.TicksPerSecond = 0, " yes", " NO")
			dc.l kw_ticks, tmp0
			dc.l kw_cpnevv, tmp0, var_t
			dc.l kw_ftov, tmp0
			dc.l kw_orvl, tmp0, -1, tmp0
			dc.l kw_goto_ifzero, tmp0, ch2_0
			dc.l kw_strcpy, stmp0, str9
			dc.l ch2_e_go
ch2_0:
			dc.l kw_strcpy, stmp0, str10
			dc.l ch2_e_go
ch2_1:
			dc.l kw_strcpy, stmp0, str11
ch2_e:
			dc.l kw_printstrvar, str12
			dc.l kw_printstrvar, stmp0
			dc.l kw_printnl

			; main.bas 31: Print "A file that isn't there"
			dc.l kw_printstrvar, str13
			dc.l kw_printnl

			; main.bas 32: Print "(AMSDOS may print its message):"
			dc.l kw_printstrvar, str14
			dc.l kw_printnl

			; main.bas 33: r = FileSystem.Load("NOFILE.DAT", VarPtr(b), 20)
			dc.l kw_ztov, var_r

			; main.bas 34: Print "Load NOFILE.DAT:"; r; " (NotFound is -2)"
			dc.l kw_printstrvar, str16
			dc.l kw_printint, var_r
			dc.l kw_printstrvar, str17
			dc.l kw_printnl

			; main.bas 35: Wait
			dc.l p_wait_c

			; main.bas 37: Mode 2
			dc.l kw_model, 2

			; main.bas 38: Print "Mode 2 (80 columns): saving again..."
			dc.l kw_printstrvar, str18
			dc.l kw_printnl

			; main.bas 39: r = FileSystem.Save("AMS2.DAT", VarPtr(a), 20)
			dc.l kw_ztov, var_r

			; main.bas 40: Print "Save AMS2.DAT:"; r; " - this line should still be 80 columns, under the one above"
			dc.l kw_printstrvar, str20
			dc.l kw_printint, var_r
			dc.l kw_printstrvar, str21
			dc.l kw_printnl

			; main.bas 41: Wait
			dc.l p_wait_c

			; main.bas 43: Mode 1
			dc.l kw_model, 1

			; main.bas 44: Print "B = try drive B, any other key = skip"
			dc.l kw_printstrvar, str22
			dc.l kw_printnl

			; main.bas 45: Do While Inkey <> 0 : Loop
do3_t:
			dc.l kw_inkey, tmp0
			dc.l kw_cpnevl, tmp0, 0
			dc.l kw_goto_iffalse, do3_e
			dc.l do3_t_go
do3_e:

			; main.bas 46: Do : k = Inkey : Frame : Loop Until k <> 0
do4_t:
			dc.l kw_inkey, tmp0
			dc.l kw_vtov, tmp0, var_k
			dc.l kw_frame
			dc.l kw_cpnevl, var_k, 0
			dc.l kw_goto_iffalse, do4_t
do4_e:

			; main.bas 47: If k = 66 Or k = 98 Then
			dc.l kw_cpeqvl, var_k, 66
			dc.l kw_ftov, tmp0
			dc.l kw_cpeqvl, var_k, 98
			dc.l kw_ftov, tmp1
			dc.l kw_orvv, tmp0, tmp1, tmp0
			dc.l kw_goto_ifzero, tmp0, if5_1

			; main.bas 48: Print "SelectVolume B:"; FileSystem.SelectVolume("B")
			dc.l kw_printstrvar, str24
			dc.l kw_printnl

			; main.bas 49: r = FileSystem.Save("AMS3.DAT", VarPtr(a), 20)
			dc.l kw_ztov, var_r

			; main.bas 50: Print "Save B:AMS3.DAT:"; r
			dc.l kw_printstrvar, str26
			dc.l kw_printint, var_r
			dc.l kw_printnl

			; main.bas 51: r = FileSystem.Load("AMS3.DAT", VarPtr(b), 20)
			dc.l kw_ztov, var_r

			; main.bas 52: Print "Load:"; r; " -"; b(0)
			dc.l kw_printstrvar, str27
			dc.l kw_printint, var_r
			dc.l kw_printstrvar, str7
			dc.l kw_printint, arr_b
			dc.l kw_printnl

			; main.bas 53: r = FileSystem.SelectVolume("A")
			dc.l kw_ztov, var_r

			; main.bas 54: Print "Volumes now "; FileSystem.Volumes()
			dc.l kw_printstrvar, str29
			dc.l kw_printnl

			; main.bas 55: End If
if5_1:

			; main.bas 56: Print "done"
			dc.l kw_printstrvar, str30
			dc.l kw_printnl

			; main.bas 57: End
			dc.l kw_printnl0
			dc.l kw_printstrvar, str31
			dc.l kw_waitkey
			dc.l kw_stop

; ============================================================
; sub wait (turbo mode)
; ============================================================

p_wait:

			; main.bas 60: Print "Press a key"
			dc.l kw_printstrvar, str31
			dc.l kw_printnl

			; main.bas 61: Do While Inkey <> 0 : Loop
do6_t:
			dc.l kw_inkey, tmp0
			dc.l kw_cpnevl, tmp0, 0
			dc.l kw_goto_iffalse, do6_e
			dc.l do6_t_go
do6_e:

			; main.bas 62: Do : Frame : Loop Until Inkey <> 0
do7_t:
			dc.l kw_frame
			dc.l kw_inkey, tmp0
			dc.l kw_cpnevl, tmp0, 0
			dc.l kw_goto_iffalse, do7_t
do7_e:
			dc.l p_wait_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

ch2_e_go:			lea ch2_e, sp
			rts
do3_t_go:			lea do3_t, sp
			rts
do6_t_go:			lea do6_t, sp
			rts

p_wait_c:		; call wait
			move.l sp, p_wait_rs
			lea p_wait, sp
			rts
p_wait_r:		; end of wait
			movea.l p_wait_rs, sp
			rts

; ============================================================
; Variables
; ============================================================

; (68000: in the RAM block at the end, from $FF8000)

; numbers passed by address (read only)
			even
ntc_aptab:		dc.l 0		; AddressOf: the procedures CallAddr runs, by number
vp_arr_a:			dc.w (arr_a)&$FFFF	; VarPtr: the address, 16 bits (RAM from $FF8000)
vp_arr_b:			dc.w (arr_b)&$FFFF	; VarPtr: the address, 16 bits (RAM from $FF8000)

; ============================================================
; Strings
; ============================================================

str0:			dc.b "TI89", 0
str1:			dc.b "AMSDOS test on TI89", 0
str2:			dc.b "Devices 0 - using 0", 0
str3:			dc.b "Volumes 0 - using 0", 0
str4:			dc.b "AMS1.DAT", 0
str5:			dc.b "Save AMS1.DAT:", 0
str6:			dc.b "Load AMS1.DAT:", 0
str7:			dc.b " -", 0
str8:			dc.b " ...", 0
str9:			dc.b " yes", 0
str10:			dc.b " NO", 0
str11:			dc.b 0
str12:			dc.b "Ticks still counting:", 0
str13:			dc.b "A file that isn't there", 0
str14:			dc.b "(AMSDOS may print its message):", 0
str15:			dc.b "NOFILE.DAT", 0
str16:			dc.b "Load NOFILE.DAT:", 0
str17:			dc.b " (NotFound is -2)", 0
str18:			dc.b "Mode 2 (80 columns): saving again...", 0
str19:			dc.b "AMS2.DAT", 0
str20:			dc.b "Save AMS2.DAT:", 0
str21:			dc.b " - this line should still be 80 columns, under the one above", 0
str22:			dc.b "B = try drive B, any other key = skip", 0
str23:			dc.b "B", 0
str24:			dc.b "SelectVolume B:0", 0
str25:			dc.b "AMS3.DAT", 0
str26:			dc.b "Save B:AMS3.DAT:", 0
str27:			dc.b "Load:", 0
str28:			dc.b "A", 0
str29:			dc.b "Volumes now 0", 0
str30:			dc.b "done", 0
str31:			dc.b "Press a key", 0
			even

; ============================================================
; Keyword library (used)
; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## kw_goto_ifzero
;kw_goto_ifzero, <var>, <label>  - branch if var = 0
kw_goto_ifzero:
			movea.l (sp)+, a0
			tst.w (a0)
			beq kw_giz_go
			addq.l #4, sp
			rts
kw_giz_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			addq.w #1, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			bge ntc_for_take		; limit >= var
			addq.l #4, sp
			rts

			even
;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), (a1)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_ftov
;kw_ftov, <destvar>  - Z flag to var: true = -1, false = 0
kw_ftov:
			seq d0
			ext.w d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

; ============================================================
; Arithmetic (16 bit, wrapping)
; ============================================================

			even
;## kw_sublv
;kw_sublv, <literal>, <var>, <destvar>  - literal - var
kw_sublv:
			move.l (sp)+, d0
			movea.l (sp)+, a1
			sub.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvl
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			muls.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_orvv
kw_orvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			or.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_orvl
kw_orvl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			or.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_cmp
; tails: d0 = a, d1 = b, test a <rel> b
ntc_cmp_slt:
			cmp.w d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_cmp_sle:
			cmp.w d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_cmp_sgt:
			cmp.w d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_cmp_sge:
			cmp.w d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_cmp_ult:
			cmp.w d1, d0
			scs d0
			addq.b #1, d0
			rts
ntc_cmp_ule:
			cmp.w d1, d0
			sls d0
			addq.b #1, d0
			rts
ntc_cmp_ugt:
			cmp.w d1, d0
			shi d0
			addq.b #1, d0
			rts
ntc_cmp_uge:
			cmp.w d1, d0
			scc d0
			addq.b #1, d0
			rts
ntc_cmp_eq:
			cmp.w d1, d0
			rts
ntc_cmp_ne:
			cmp.w d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_cpeqvl
kw_cpeqvl:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			cmp.w (a0), d1
			rts

			even
;## kw_cpnevv ntc_cmp
kw_cpnevv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_ne

			even
;## kw_cpnevl ntc_cmp
kw_cpnevl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_ne

; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE). An Integer address is sign extended:
; 0-32767 = the ROM's first 32K, -32768..-1 = RAM $FF8000-$FFFFFF
; (where the variables are). DEEK / DOKE need an even address.
; ============================================================

			even
;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			add.l d0, d0
			movea.l (sp)+, a1
			move.w (a1), 0(a0, d0.l)
			rts

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## kw_inkey ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_scankey
			NTC_TS
			andi.w #$FF, d0
			move.w d0, (a2)
			rts

			even
;## kw_model ntc_data ntc_plat_screen
;kw_model, <literal>  - clears the screen
kw_model:
			move.l (sp)+, d0
			NTC_RS
			jsr ntc_plat_mode
			NTC_TS
			rts

			even
;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame (vertical blank)
kw_frame:
			NTC_RS
			jsr ntc_plat_frame
			NTC_TS
			rts

			even
;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - the tick count (frames, 60 or 50 a second)
kw_ticks:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_ticks
			NTC_TS
			move.w d0, (a2)
			rts

; ============================================================
; String functions. Numbers are passed as the address of a word.
; Results go to a string buffer. Dest may be the same as the source.
; ============================================================

			even
;## kw_bssinit ntc_data ntc_plat_screen
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the RAM variables (not in the ROM). Check they fit under the end of RAM, then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			andi.l #$FFFF, d0
			move.l a0, d1
			add.l d0, d1
			cmpi.l #$01000000, d1
			bhi kw_bs_big
			tst.l d0
			beq kw_bs_e
kw_bs_lp:
			clr.b (a0)+
			subq.l #1, d0
			bne kw_bs_lp
kw_bs_e:
			rts
kw_bs_big:
			NTC_RS
			lea kw_bs_txt, a2
kw_bs_pl:
			moveq #0, d0
			move.b (a2)+, d0
			beq kw_bs_stop
			jsr ntc_plat_putc
			bra kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp kw_stop
kw_bs_txt:	dc.b "GURU 001", 0
			even

			even
;## ntc_ti89_boot ntc_plat_data ntc_data ntc_plat_screen
ntc_ti89_boot:
			; AMS entered us in user mode with a valid stack; clear the screen
			; and hand control to the thread (the compiler's start code follows,
			; sets A7 to the thread and runs).
			jsr ntc_ti89_clear
			rts

			even
;## ntc_plat_data ntc_data
; ------------------------------------------------------------
; UNVERIFIED hardware values - every one is a guess.  ;!!TI89? confirm all.
; ------------------------------------------------------------
LCD_MEM     equ $4C00           ; LCD bitmap base in RAM          ;!!TI89? guess
ROWBYTES    equ 30              ; bytes per pixel row (240/8; the 89 is 20) ;!!TI89?
SCRROWS     equ 128             ; pixel rows (the 89 is 100)       ;!!TI89?

ntc_curx:   dc.w 0              ; text column (0..cols-1)
ntc_cury:   dc.w 0              ; text row (0..rows-1)
ntc_frames: dc.w 0              ; frame counter (ntc_plat_ticks)

			even
;## ntc_plat_screen ntc_plat_data ntc_data
; platform routines: entered with jsr, end with rts (real stack), keeping
; d2-d7 / a2-a6 (the 68k backend's convention).

; ntc_ti89_celladdr - a0 = LCD byte address of the top row of cell (curx,cury).
; addr = LCD_MEM + cury*8*ROWBYTES + curx   (8px-wide font = 1 byte per column)
ntc_ti89_celladdr:
			move.w ntc_cury, d1
			lsl.w #3, d1               ; row * 8 pixel rows
			mulu #ROWBYTES, d1
			add.w ntc_curx, d1
			lea LCD_MEM, a0
			adda.w d1, a0
			rts

; ntc_plat_putc - d0.b = character 32..127: blit its 8x8 glyph, advance
ntc_plat_putc:
			and.w #$00FF, d0
			sub.w #32, d0
			bge.s ntc_pc_ok
			moveq #0, d0               ; below space -> space
ntc_pc_ok:
			lsl.w #3, d0               ; glyph = font + char*8
			lea ntc_ti89_font, a1
			adda.w d0, a1
			jsr ntc_ti89_celladdr
			moveq #7, d2               ; 8 rows
ntc_pc_row:
			move.b (a1)+, (a0)
			adda.w #ROWBYTES, a0
			dbra d2, ntc_pc_row
			addq.w #1, ntc_curx
			cmp.w #30, ntc_curx        ; cols ;!!TI89? (89 = 20)
			blt.s ntc_pc_done
			jsr ntc_plat_newline
ntc_pc_done:
			rts

; ntc_plat_newline - column 0, next row; scroll not done yet ;!!TI89? scroll
ntc_plat_newline:
			clr.w ntc_curx
			addq.w #1, ntc_cury
			cmp.w #16, ntc_cury        ; rows ;!!TI89? (89 = 12)
			blt.s ntc_nl_done
			move.w #15, ntc_cury
ntc_nl_done:
			rts

; ntc_ti89_clear - blank the whole LCD bitmap
ntc_ti89_clear:
			lea LCD_MEM, a0
			move.w #ROWBYTES*SCRROWS-1, d1
ntc_cl_lp:
			clr.b (a0)+
			dbra d1, ntc_cl_lp
			clr.w ntc_curx
			clr.w ntc_cury
			rts

			even
;## ntc_plat_mode @unit ntc_plat_screen ntc_plat_data ntc_data
ntc_plat_mode:
			rts

			even
;## ntc_plat_key ntc_plat_data ntc_data
; ntc_plat_scankey - d0.b = a key or 0.  ;!!TI89? the 68k calc key matrix is a
; memory-mapped port read (row strobe / column read); the exact addresses were
; NOT grounded, so this is a stub returning "no key". Wire the port + a code
; map before Inkey works. (An AMS build would ROM_CALL ngetchx instead.)
ntc_plat_scankey:
			moveq #0, d0               ; ;!!TI89? no key matrix read yet
			rts

; ntc_plat_getkey - wait for a key (spins on the stub above until wired)
ntc_plat_getkey:
			jsr ntc_plat_scankey
			tst.b d0
			beq.s ntc_plat_getkey
			rts

			even
;## ntc_plat_frame ntc_plat_data ntc_data
; ntc_plat_frame - bump the counter. ;!!TI89? a real build waits the LCD frame
; (AMS keeps a timer; or poll the LCD controller).
ntc_plat_frame:
			addq.w #1, ntc_frames
			rts

			even
;## ntc_plat_ticks ntc_plat_data ntc_data
; ntc_plat_ticks - d0.w = frame counter. ;!!TI89? AMS has a real timer to read.
ntc_plat_ticks:
			move.w ntc_frames, d0
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - return to AMS. ;!!TI89? a nostub program returns with rts to
; the kernel; this restores nothing special yet.
ntc_plat_exit:
			rts


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $FF8000
ntc_ram:
; variables
var_i:			dc.w 0
var_r:			dc.w 0
var_t:			dc.w 0
var_k:			dc.w 0
p_wait_rs:			dc.l 0
tmp0:			dc.w 0
tmp1:			dc.w 0
tmp2:			dc.w 0
			dc.b 40			; capacity
stmp0:			ds.b 41
			even
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_a		equ ntc_bss + 0		; 20 bytes
arr_b		equ ntc_bss + 20		; 20 bytes
ntc_bss_size	equ 40
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
